/**
 * Helper Utilities
 * Common functions used across nodes
 */

/**
 * Convert time string to seconds
 * Supports: 's' (seconds), 'm' (minutes), 'h' (hours), 'd' (days)
 * @param {string} timeString - Time string (e.g., "5m", "2h", "1d")
 * @returns {number} Time in seconds
 */
function timeToSeconds(timeString) {
  const match = timeString.match(/^(\d+)([smhd])$/);
  
  if (!match) {
    console.warn(`Invalid time format: ${timeString}, defaulting to seconds`);
    return parseInt(timeString) || 0;
  }

  const value = parseInt(match[1]);
  const unit = match[2];

  const conversions = {
    's': 1,
    'm': 60,
    'h': 3600,
    'd': 86400
  };

  return value * (conversions[unit] || 1);
}

/**
 * Validate phone number format
 * @param {string} phoneNumber - Phone number to validate
 * @returns {boolean}
 */
function isValidPhoneNumber(phoneNumber) {
  if (!phoneNumber) return false;
  
  // Remove non-numeric characters
  const cleaned = phoneNumber.replace(/\D/g, '');
  
  // Valid African phone numbers typically have 9-15 digits
  return cleaned.length >= 9 && cleaned.length <= 15;
}

/**
 * Resolve variable from message
 * Supports dot notation: ${user.name}, ${data.value}
 * @param {string} message - Message with variables
 * @param {Object} variables - Variables object
 * @returns {string} Message with variables replaced
 */
function resolveVariables(message, variables = {}) {
  if (!message || typeof message !== 'string') {
    return message;
  }

  return message.replace(/\$\{([\w.]+)\}/g, (match, key) => {
    const keys = key.split('.');
    let value = variables;

    for (const k of keys) {
      if (value && typeof value === 'object') {
        value = value[k];
      } else {
        return match; // Return original if key not found
      }
    }

    return value !== undefined ? String(value) : match;
  });
}

/**
 * Parse CSV string to array
 * Simple implementation - for complex CSV use csvtojson package
 * @param {string} csvString - CSV data
 * @returns {Array<Object>}
 */
function parseSimpleCSV(csvString) {
  const lines = csvString.trim().split('\n');
  if (lines.length === 0) return [];

  const headers = lines[0].split(',').map(h => h.trim());
  const result = [];

  for (let i = 1; i < lines.length; i++) {
    const obj = {};
    const values = lines[i].split(',').map(v => v.trim());
    
    headers.forEach((header, index) => {
      obj[header] = values[index] || '';
    });

    result.push(obj);
  }

  return result;
}

/**
 * Delay execution for specified milliseconds
 * @param {number} ms - Milliseconds to wait
 * @returns {Promise}
 */
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Generate unique message ID
 * @returns {string}
 */
function generateMessageId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

/**
 * Safe JSON parse with fallback
 * @param {string} jsonString - JSON string to parse
 * @param {*} fallback - Fallback value if parse fails
 * @returns {*}
 */
function safeJsonParse(jsonString, fallback = null) {
  try {
    return JSON.parse(jsonString);
  } catch (error) {
    console.warn('JSON parse error:', error.message);
    return fallback;
  }
}

/**
 * Merge objects recursively
 * @param {Object} target - Target object
 * @param {Object} source - Source object
 * @returns {Object} Merged object
 */
function deepMerge(target, source) {
  const result = { ...target };

  Object.keys(source).forEach(key => {
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      result[key] = deepMerge(result[key] || {}, source[key]);
    } else {
      result[key] = source[key];
    }
  });

  return result;
}

/**
 * Validate email format
 * @param {string} email - Email to validate
 * @returns {boolean}
 */
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

/**
 * Get timeout from config (supports multiple time units)
 * @param {Object} timeConfig - Config with value and unit
 * @returns {number} Timeout in milliseconds
 */
function getTimeoutMs(timeConfig) {
  if (typeof timeConfig === 'number') {
    return timeConfig * 1000; // Assume seconds
  }

  if (typeof timeConfig === 'string') {
    const seconds = timeToSeconds(timeConfig);
    return seconds * 1000;
  }

  if (timeConfig && typeof timeConfig === 'object') {
    const { value, unit = 's' } = timeConfig;
    const seconds = value * (unit === 's' ? 1 : unit === 'm' ? 60 : unit === 'h' ? 3600 : 86400);
    return seconds * 1000;
  }

  return 30000; // Default 30 seconds
}

/**
 * Format response data for storage
 * @param {Object} response - Response data
 * @returns {Object} Formatted response
 */
function formatResponseData(response) {
  return {
    content: response.content || response.message || '',
    type: response.type || 'text',
    rawData: response.rawData || response,
    processedAt: new Date().toISOString()
  };
}

module.exports = {
  timeToSeconds,
  isValidPhoneNumber,
  resolveVariables,
  parseSimpleCSV,
  delay,
  generateMessageId,
  safeJsonParse,
  deepMerge,
  isValidEmail,
  getTimeoutMs,
  formatResponseData
};